discrete ReactorSystem
port:
    event input real StartCommand;
    event input real ShutdownCommand;
    event output real HeatProvided;
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(StartCommand) then
            transition(StartupState);
        end;
    end;

    state StartupState
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(RunningState);
            out
                send(HeatProvided, 1);
        end;
    end;

    state RunningState
        when entry() then
            statehold(0);
        end;
        when receive(ShutdownCommand) then
            transition(CoolingState);
        end;
    end;

    state CoolingState
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

discrete HeatExchangerSystem
port:
    event input real HeatProvided;
    event output real SteamGenerated;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(HeatProvided) then
            transition(WorkingState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(0);
        end;
        when !receive(HeatProvided) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete SteamTurbineSystem
port:
    event input real SteamGenerated;
    event output real PowerGenerated;
state:
    initial state ReadyState
        when entry() then
            statehold(0);
        end;
        when receive(SteamGenerated) then
            transition(RotatingState);
        end;
    end;

    state RotatingState
        when entry() then
            statehold(0);
        end;
        when !receive(SteamGenerated) then
            transition(ReadyState);
        end;
    end;
end;
end;

discrete PowerTransmissionSystem
port:
    event input real PowerGenerated;
    event output real PowerDelivered;
state:
    initial state NoLoadState
        when entry() then
            statehold(0);
        end;
        when receive(PowerGenerated) then
            transition(SupplyingState);
        end;
    end;

    state SupplyingState
        when entry() then
            statehold(0);
        end;
        when !receive(PowerGenerated) then
            transition(NoLoadState);
        end;
    end;
end;
end;

couple NuclearPowerSystem
import architectureModels.ReactorSystem as Reactor;
import architectureModels.HeatExchangerSystem as HeatExchanger;
import architectureModels.SteamTurbineSystem as SteamTurbine;
import architectureModels.PowerTransmissionSystem as PowerTransmission;

part:
    Reactor ReactorInstance;
    HeatExchanger HeatExchangerInstance;
    SteamTurbine SteamTurbineInstance;
    PowerTransmission PowerTransmissionInstance;

connection:
    connect(ReactorInstance.HeatProvided, HeatExchangerInstance.HeatProvided);
    connect(HeatExchangerInstance.SteamGenerated, SteamTurbineInstance.SteamGenerated);
    connect(SteamTurbineInstance.PowerGenerated, PowerTransmissionInstance.PowerGenerated);
end;
